  const indexingStore = createIndexingStore({
    common,
    schemaBuild: { schema },
    indexingCache,
    indexingErrorHandler,
  });

  indexingStore.qb = database.userQB;
  indexingCache.qb = database.userQB;

  const indexing = createIndexing({
